long total = 1_000_000, fraud = total / 1000, legit = total - fraud;
long caught = Math.round(fraud * 0.80);       // recall 80%
long wrongful = Math.round(legit * 0.005);    // chặn nhầm 0,5% khách thật
System.out.printf("%d %d %.1f%%%n", caught, wrongful, 100.0 * caught / (caught + wrongful));
